WITH with_prev AS (SELECT *, LAG(started_at) OVER (PARTITION BY browser ORDER BY started_at, id) AS prev_started_at FROM sessions), flagged AS (SELECT *, CASE WHEN prev_started_at IS NULL OR started_at > prev_started_at + INTERVAL '60' DAY THEN 1 ELSE 0 END AS session_start_flag FROM with_prev), sessions_sessions AS (SELECT id, browser, started_at, country, SUM(session_start_flag) OVER (PARTITION BY browser ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM flagged) SELECT CASE WHEN session_no >= 8 THEN 'HIGH' ELSE 'LOW' END AS session_no_tier, DATE_TRUNC('YEAR', started_at) AS year_start, COUNT(*) AS num_rows, COUNT_IF(country = 'US') AS us_events, AVG(session_no) FILTER (WHERE country = 'DE') AS de_avg_session_no, GROUPING(CASE WHEN session_no >= 8 THEN 'HIGH' ELSE 'LOW' END) AS grouping_level FROM sessions_sessions GROUP BY ROLLUP (CASE WHEN session_no >= 8 THEN 'HIGH' ELSE 'LOW' END, DATE_TRUNC('YEAR', started_at)) ORDER BY year_start DESC
